INSERT INTO recipes (title, description, target, meal_slot, baby_age_group, age_range_min_months, age_range_max_months, recipe_type, ingredients, instructions, prep_time_minutes, nutrition_info) VALUES
('Breast Milk Feed',       'Exclusive breastfeeding on demand — the perfect complete nutrition for 0–6 months.', 'baby', 'breakfast', '0-6', 0, 6, 'puree', ARRAY['Breast milk'], ARRAY['Feed on demand, typically every 2–3 hours.'], 0, '{"note":"Complete nutrition — no solids needed at this stage"}'),
('Formula Feed',           'Iron-fortified infant formula as alternative to breast milk.', 'baby', 'breakfast', '0-6', 0, 6, 'puree', ARRAY['Infant formula powder','Boiled cooled water'], ARRAY['Measure water first.','Add correct scoops of formula.','Shake gently and feed at body temperature.'], 5, '{"note":"Follow tin instructions for correct ratio"}'),
('Breast Milk — Midday',   'Daytime breastfeeding session.', 'baby', 'lunch',     '0-6', 0, 6, 'puree', ARRAY['Breast milk'], ARRAY['Feed on demand.'], 0, '{}'),
('Formula — Midday',       'Midday formula bottle.', 'baby', 'lunch', '0-6', 0, 6, 'puree', ARRAY['Infant formula powder','Boiled cooled water'], ARRAY['Prepare as per tin instructions.'], 5, '{}'),
('Evening Breast Milk',    'Evening breastfeeding session.', 'baby', 'dinner', '0-6', 0, 6, 'puree', ARRAY['Breast milk'], ARRAY['Feed on demand.'], 0, '{}'),
('Bedtime Formula Bottle', 'Settling formula feed before sleep.', 'baby', 'snack', '0-6', 0, 6, 'puree', ARRAY['Infant formula powder','Boiled cooled water'], ARRAY['Prepare a slightly larger feed before bed to promote longer sleep.'], 5, '{}');
INSERT INTO recipes (title, description, target, meal_slot, baby_age_group, age_range_min_months, age_range_max_months, recipe_type, ingredients, instructions, prep_time_minutes, cooking_time_minutes, nutrition_info) VALUES
('Rice Cereal Porridge',   'Smooth iron-fortified rice cereal — ideal first breakfast.', 'baby', 'breakfast', '7-11', 7, 11, 'puree', ARRAY['2 tbsp iron-fortified rice cereal','3–4 tbsp breast milk or formula'], ARRAY['Mix cereal with warm breast milk or formula.','Stir to smooth consistency.','Serve warm.'], 3, 0, '{"iron":"high","calories":60}'),
('Banana & Oat Puree',     'Naturally sweet banana blended with soft cooked oats.', 'baby', 'breakfast', '7-11', 7, 11, 'puree', ARRAY['½ ripe banana','2 tbsp rolled oats','3 tbsp water or formula'], ARRAY['Cook oats in water until soft (5 min).','Mash banana.','Mix together and blend until smooth.'], 5, 5, '{"potassium":"high","fiber":"medium","calories":90}'),
('Apple Cinnamon Porridge','Gently spiced apple and oat puree rich in fibre.', 'baby', 'breakfast', '7-11', 7, 11, 'puree', ARRAY['1 small apple (peeled)','2 tbsp oats','Pinch of cinnamon','Water'], ARRAY['Peel, core and chop apple.','Steam or simmer until soft (8 min).','Cook oats separately.','Blend apple with oats and a pinch of cinnamon.'], 5, 10, '{"fiber":"high","vitamin_c":"medium","calories":85}'),
('Sweet Potato Mash',      'Naturally sweet and creamy sweet potato puree.', 'baby', 'breakfast', '7-11', 7, 11, 'puree', ARRAY['1 small sweet potato','2 tbsp breast milk or formula'], ARRAY['Peel and cube sweet potato.','Steam for 15 min until tender.','Mash well adding milk to reach smooth consistency.'], 5, 15, '{"vitamin_a":"high","potassium":"high","calories":95}');
INSERT INTO recipes (title, description, target, meal_slot, baby_age_group, age_range_min_months, age_range_max_months, recipe_type, ingredients, instructions, prep_time_minutes, cooking_time_minutes, nutrition_info) VALUES
('Carrot & Lentil Soup',   'Iron-rich lentils with sweet carrot — perfect first protein meal.', 'baby', 'lunch', '7-11', 7, 11, 'puree', ARRAY['2 tbsp red lentils','1 small carrot','2 cups water'], ARRAY['Rinse lentils.','Peel and chop carrot.','Simmer together 20 min until soft.','Blend to smooth puree.'], 5, 20, '{"iron":"high","protein":"medium","vitamin_a":"high","calories":110}'),
('Pea & Potato Puree',     'Mild and creamy pea and potato blend packed with vitamins.', 'baby', 'lunch', '7-11', 7, 11, 'puree', ARRAY['¼ cup frozen peas','1 small potato','Water'], ARRAY['Peel and cube potato; steam 15 min.','Add peas for last 5 min.','Blend together to smooth puree.'], 5, 15, '{"vitamin_c":"high","fiber":"medium","calories":95}'),
('Butternut Squash & Apple','Sweet squash with apple makes a naturally tasty combo.', 'baby', 'lunch', '7-11', 7, 11, 'puree', ARRAY['¼ butternut squash','½ apple'], ARRAY['Peel and cube squash; steam 15 min.','Peel, core and chop apple; steam 8 min.','Blend together until smooth.'], 5, 15, '{"vitamin_a":"very_high","fiber":"medium","calories":80}'),
('Chicken & Vegetable Puree','First protein introduction with mild chicken and vegetables.', 'baby', 'lunch', '7-11', 7, 11, 'puree', ARRAY['30g chicken breast','1 small carrot','¼ cup peas','Water'], ARRAY['Simmer chicken in water 15 min until cooked.','Steam carrot and peas separately.','Blend everything together adding cooking water for consistency.'], 5, 20, '{"protein":"high","iron":"medium","zinc":"medium","calories":120}');
INSERT INTO recipes (title, description, target, meal_slot, baby_age_group, age_range_min_months, age_range_max_months, recipe_type, ingredients, instructions, prep_time_minutes, cooking_time_minutes, nutrition_info) VALUES
('Broccoli & Cheese Mash', 'Calcium-rich cheese mixed into smooth broccoli.', 'baby', 'dinner', '7-11', 7, 11, 'puree', ARRAY['4 broccoli florets','1 tbsp mild cheddar (grated)','1 tbsp milk'], ARRAY['Steam broccoli 8 min until tender.','Blend with cheese and milk to smooth puree.'], 5, 8, '{"calcium":"high","vitamin_c":"high","calories":85}'),
('Lentil & Spinach Dal',   'Iron-packed dal — easy first taste of legumes.', 'baby', 'dinner', '7-11', 7, 11, 'puree', ARRAY['2 tbsp red lentils','Handful baby spinach','½ tsp mild cumin','Water'], ARRAY['Cook lentils in water 20 min.','Add spinach last 3 min.','Blend with a pinch of cumin to smooth consistency.'], 5, 20, '{"iron":"very_high","folate":"high","calories":105}'),
('Fish & Sweet Potato',    'Omega-3 rich white fish with sweet potato for brain development.', 'baby', 'dinner', '7-11', 7, 11, 'puree', ARRAY['40g white fish fillet','1 small sweet potato'], ARRAY['Steam sweet potato 15 min.','Poach fish in water 8 min; check for bones.','Blend together to smooth puree.'], 5, 15, '{"omega3":"high","vitamin_a":"high","protein":"high","calories":130}');
INSERT INTO recipes (title, description, target, meal_slot, baby_age_group, age_range_min_months, age_range_max_months, recipe_type, ingredients, instructions, prep_time_minutes, nutrition_info) VALUES
('Mango Puree',            'Ripe mango puree — naturally sweet vitamin C snack.', 'baby', 'snack', '7-11', 7, 11, 'puree', ARRAY['½ ripe mango'], ARRAY['Peel and remove seed.','Blend to smooth puree.'], 3, '{"vitamin_c":"high","vitamin_a":"medium","calories":65}'),
('Pear & Ginger Puree',    'Gentle pear with a hint of ginger to aid digestion.', 'baby', 'snack', '7-11', 7, 11, 'puree', ARRAY['1 ripe pear','Tiny pinch of ginger'], ARRAY['Peel, core and chop pear.','Steam 8 min.','Blend with pinch of ginger.'], 3, '{"fiber":"medium","calories":55}'),
('Avocado Mash',           'Creamy avocado rich in healthy fats for brain development.', 'baby', 'snack', '7-11', 7, 11, 'puree', ARRAY['¼ ripe avocado'], ARRAY['Scoop out avocado flesh.','Mash with fork to smooth consistency.'], 2, '{"healthy_fats":"high","calories":80}');
INSERT INTO recipes (title, description, target, meal_slot, baby_age_group, age_range_min_months, age_range_max_months, recipe_type, ingredients, instructions, prep_time_minutes, cooking_time_minutes, nutrition_info) VALUES
('Egg & Toast Soldiers',   'Soft scrambled egg with toast fingers — great self-feeding practice.', 'baby', 'breakfast', '12-17', 12, 17, 'finger_food', ARRAY['1 egg','1 slice wholegrain bread','1 tsp butter'], ARRAY['Scramble egg gently in butter over low heat.','Toast bread and cut into strips.','Serve egg alongside toast soldiers.'], 5, 5, '{"protein":"high","iron":"medium","calories":160}'),
('Banana Pancakes',        'Two-ingredient banana egg pancakes — no sugar needed.', 'baby', 'breakfast', '12-17', 12, 17, 'finger_food', ARRAY['1 ripe banana','1 egg','1 tsp coconut oil'], ARRAY['Mash banana; whisk with egg.','Heat oil in pan over medium heat.','Pour small rounds; cook 2 min per side.','Serve cut into strips.'], 5, 10, '{"potassium":"high","protein":"medium","calories":140}'),
('Overnight Oats',         'Creamy oats soaked overnight with fruit — no cooking needed.', 'baby', 'breakfast', '12-17', 12, 17, 'meal', ARRAY['3 tbsp rolled oats','½ cup whole milk','¼ banana','1 tbsp mashed berries'], ARRAY['Mix oats and milk; refrigerate overnight.','Top with mashed banana and berries in the morning.'], 3, 0, '{"calcium":"high","fiber":"high","calories":175}'),
('Cheesy Veggie Omelette', 'Mini omelette loaded with soft vegetables and cheese.', 'baby', 'breakfast', '12-17', 12, 17, 'meal', ARRAY['1 egg','1 tbsp grated cheese','2 tbsp finely chopped soft veg (pea, carrot)','Butter'], ARRAY['Whisk egg; stir in cheese and veg.','Cook in buttered pan 3 min until set.','Cut into strips for easy eating.'], 5, 5, '{"protein":"high","calcium":"medium","calories":150}');
INSERT INTO recipes (title, description, target, meal_slot, baby_age_group, age_range_min_months, age_range_max_months, recipe_type, ingredients, instructions, prep_time_minutes, cooking_time_minutes, nutrition_info) VALUES
('Mini Pasta with Tomato', 'Soft pasta stars in mild tomato sauce — a toddler favourite.', 'baby', 'lunch', '12-17', 12, 17, 'meal', ARRAY['¼ cup small pasta','2 tbsp no-salt tomato puree','1 tsp olive oil','Pinch of basil'], ARRAY['Cook pasta as per packet until very soft.','Warm tomato puree with olive oil and basil.','Toss pasta in sauce and serve.'], 5, 10, '{"carbs":"high","iron":"medium","calories":165}'),
('Lentil Veggie Patties',  'Soft lentil and vegetable patties — easy to hold and rich in iron.', 'baby', 'lunch', '12-17', 12, 17, 'finger_food', ARRAY['¼ cup red lentils (cooked)','2 tbsp mashed carrot','2 tbsp mashed pea','1 tbsp breadcrumbs','1 egg'], ARRAY['Mash lentils; mix with veg, breadcrumbs and egg.','Form into small flat patties.','Bake at 180°C for 15 min, flipping halfway.'], 10, 15, '{"iron":"high","protein":"high","fiber":"medium","calories":145}'),
('Chicken Rice Bowl',      'Tender shredded chicken with soft rice and steamed veg.', 'baby', 'lunch', '12-17', 12, 17, 'meal', ARRAY['30g cooked chicken (shredded)','¼ cup cooked rice','Steamed broccoli florets','1 tsp olive oil'], ARRAY['Shred cooked chicken finely.','Mix warm rice and chicken.','Top with small broccoli pieces and drizzle oil.'], 5, 0, '{"protein":"high","zinc":"medium","calories":180}'),
('Hummus & Veggie Strips', 'Creamy hummus with soft steamed vegetable strips for dipping.', 'baby', 'lunch', '12-17', 12, 17, 'finger_food', ARRAY['2 tbsp hummus','Soft steamed carrot strips','Soft cucumber strips','Pita triangle (soft)'], ARRAY['Serve hummus in small bowl.','Arrange steamed carrot strips and cucumber.','Add soft pita triangle for dipping.'], 5, 5, '{"protein":"medium","iron":"medium","fiber":"high","calories":130}');
INSERT INTO recipes (title, description, target, meal_slot, baby_age_group, age_range_min_months, age_range_max_months, recipe_type, ingredients, instructions, prep_time_minutes, cooking_time_minutes, nutrition_info) VALUES
