('Beef & Vegetable Stew',  'Slow-cooked beef with root vegetables — great for iron.', 'baby', 'dinner', '12-17', 12, 17, 'meal', ARRAY['40g lean beef mince','1 small carrot (diced)','¼ cup potato (diced)','¼ cup peas','Water or no-salt stock'], ARRAY['Brown mince in pan.','Add vegetables and stock; simmer 25 min.','Mash slightly for appropriate texture.'], 10, 30, '{"iron":"very_high","protein":"high","zinc":"high","calories":200}'),
('Tofu & Broccoli Stir',   'Soft tofu and tender broccoli with gentle sesame.', 'baby', 'dinner', '12-17', 12, 17, 'meal', ARRAY['50g soft tofu (cubed)','4 broccoli florets','1 tsp sesame oil','1 tsp low-sodium soy sauce'], ARRAY['Steam broccoli 8 min until tender.','Pan-fry tofu in sesame oil 3 min per side.','Toss together with tiny amount of soy sauce.','Cut into small pieces before serving.'], 5, 12, '{"protein":"high","calcium":"high","iron":"medium","calories":150}');
INSERT INTO recipes (title, description, target, meal_slot, baby_age_group, age_range_min_months, age_range_max_months, recipe_type, ingredients, instructions, prep_time_minutes, nutrition_info) VALUES
