('Yogurt & Berry Bowl',    'Full-fat yogurt with mashed fresh berries.', 'baby', 'snack', '12-17', 12, 17, 'snack', ARRAY['4 tbsp full-fat plain yogurt','Handful strawberries or blueberries'], ARRAY['Mash or halve berries.','Stir into yogurt and serve.'], 3, '{"calcium":"high","vitamin_c":"high","probiotics":"yes","calories":90}'),
