INSERT INTO recipes (title, description, target, meal_slot, baby_age_group, age_range_min_months, age_range_max_months, recipe_type, ingredients, instructions, prep_time_minutes, cooking_time_minutes, nutrition_info) VALUES
('Chicken Noodle Soup',    'Warming homemade chicken noodle soup with vegetables.', 'baby', 'lunch', '31-36', 31, 36, 'meal', ARRAY['50g chicken','½ cup egg noodles','1 carrot (diced)','1 celery stalk','Low-sodium stock'], ARRAY['Simmer chicken in stock 15 min; shred.','Add noodles and veg; cook 8 min.','Serve warm.'], 5, 25, '{"protein":"high","zinc":"medium","calories":210}'),
('Cheese & Veggie Sandwich','Wholegrain sandwich with cheese, cucumber and tomato.', 'baby', 'lunch', '31-36', 31, 36, 'finger_food', ARRAY['2 slices wholegrain bread','2 slices mild cheese','Cucumber','Tomato','Lettuce'], ARRAY['Layer ingredients on bread.','Cut into triangles or squares.'], 5, 0, '{"calcium":"high","fiber":"medium","calories":215}'),
('Rainbow Salad Bowl',     'Colourful chopped salad with quinoa and mild dressing.', 'baby', 'lunch', '31-36', 31, 36, 'meal', ARRAY['¼ cup quinoa (cooked)','Cherry tomatoes (halved)','Cucumber (diced)','Sweetcorn','1 tsp olive oil','Squeeze of lemon'], ARRAY['Cook quinoa; cool.','Chop all vegetables.','Toss together with oil and lemon.'], 5, 15, '{"protein":"high","fiber":"high","vitamin_c":"high","calories":200}');
INSERT INTO recipes (title, description, target, meal_slot, baby_age_group, age_range_min_months, age_range_max_months, recipe_type, ingredients, instructions, prep_time_minutes, cooking_time_minutes, nutrition_info) VALUES
('Mild Chicken Biryani',   'Fragrant mild biryani with vegetables — family-style meal.', 'baby', 'dinner', '31-36', 31, 36, 'meal', ARRAY['60g chicken','½ cup basmati rice','Mixed veg','½ tsp mild garam masala','Yogurt'], ARRAY['Marinate chicken in yogurt and spice 20 min.','Cook rice.','Brown chicken; add veg; simmer 15 min.','Layer over rice; bake covered 15 min at 180°C.'], 25, 30, '{"protein":"high","iron":"medium","calories":280}'),
('Fish Tacos',             'Soft baked fish in mini tortillas with slaw.', 'baby', 'dinner', '31-36', 31, 36, 'meal', ARRAY['60g white fish','2 mini flour tortillas','¼ cup cabbage (shredded)','1 tbsp yogurt','Squeeze lime'], ARRAY['Bake fish at 180°C 12 min; flake.','Mix cabbage with yogurt and lime.','Fill tortillas with fish and slaw.'], 5, 15, '{"omega3":"high","protein":"high","vitamin_c":"medium","calories":255}'),
('Tomato Soup & Grilled Cheese','Classic tomato soup with mini grilled cheese triangles.', 'baby', 'dinner', '31-36', 31, 36, 'meal', ARRAY['1 cup tomato soup (no salt)','1 slice wholegrain bread','2 tbsp cheese','1 tsp butter'], ARRAY['Warm tomato soup.','Make grilled cheese sandwich; cut into triangles.','Serve together.'], 5, 10, '{"vitamin_c":"high","calcium":"high","calories":245}');
INSERT INTO recipes (title, description, target, meal_slot, baby_age_group, age_range_min_months, age_range_max_months, recipe_type, ingredients, instructions, prep_time_minutes, nutrition_info) VALUES
('Apple Slices & Nut Butter','Crisp apple slices with smooth almond or peanut butter.', 'baby', 'snack', '31-36', 31, 36, 'snack', ARRAY['1 apple','1 tbsp nut butter'], ARRAY['Slice apple.','Serve with nut butter for dipping.'], 3, '{"fiber":"high","protein":"medium","healthy_fats":"high","calories":145}'),
('Fruit Skewers',          'Colourful fruit skewers on short sticks — fun to eat.', 'baby', 'snack', '31-36', 31, 36, 'snack', ARRAY['Strawberries','Grapes (halved)','Melon chunks','Kiwi slices'], ARRAY['Thread fruit onto short skewers.','Serve immediately.'], 5, '{"vitamin_c":"very_high","fiber":"high","calories":75}'),
('Veggie Crackers & Dip',  'Whole grain crackers with cucumber tzatziki dip.', 'baby', 'snack', '31-36', 31, 36, 'snack', ARRAY['4 whole grain crackers','3 tbsp yogurt','¼ cucumber (grated)','Pinch of mint'], ARRAY['Grate cucumber; squeeze out water.','Mix with yogurt and mint.','Serve with crackers.'], 5, '{"calcium":"medium","fiber":"medium","calories":110}');
INSERT INTO recipes (title, description, target, meal_slot, age_range_min_months, age_range_max_months, recipe_type, ingredients, instructions, prep_time_minutes, cooking_time_minutes, nutrition_info) VALUES
('Warm Lemon Water',        'Start the day with a glass of warm lemon water to kickstart digestion and hydration.', 'mum', 'early_morning', 0, 36, 'meal', ARRAY['1 glass warm water','Juice of ½ lemon'], ARRAY['Warm water to comfortable temperature.','Squeeze in lemon juice.','Drink before eating.'], 2, 0, '{"vitamin_c":"high","hydration":"excellent","calories":5}'),
('Soaked Almonds & Raisins','5 soaked almonds and a few raisins — traditional postpartum energy booster.', 'mum', 'early_morning', 0, 36, 'meal', ARRAY['5 almonds (soaked overnight)','1 tbsp raisins'], ARRAY['Soak almonds overnight in water.','Peel skin and eat with raisins.'], 1, 0, '{"healthy_fats":"high","iron":"medium","calcium":"medium","calories":85}'),
('Methi Seeds Water',       'Fenugreek seed water — traditionally supports breast milk supply and digestion.', 'mum', 'early_morning', 0, 36, 'meal', ARRAY['1 tsp methi (fenugreek) seeds','1 glass warm water'], ARRAY['Soak methi seeds overnight.','Strain and drink the water in the morning.'], 1, 0, '{"iron":"high","galactagogue":"yes","calories":10}'),
('Ajwain Water',            'Carom seed water — helps relieve postpartum gas and bloating.', 'mum', 'early_morning', 0, 36, 'meal', ARRAY['½ tsp ajwain (carom) seeds','1 glass warm water'], ARRAY['Boil seeds in water 5 min.','Strain, cool slightly and drink.'], 1, 5, '{"digestive_aid":"yes","anti_bloat":"yes","calories":5}');
INSERT INTO recipes (title, description, target, meal_slot, age_range_min_months, age_range_max_months, recipe_type, ingredients, instructions, prep_time_minutes, cooking_time_minutes, nutrition_info) VALUES
('Oatmeal with Flaxseeds', 'Creamy oat porridge with flaxseeds and berries — high in DHA precursors and fibre.', 'mum', 'breakfast', 0, 36, 'meal', ARRAY['½ cup oats','1 cup whole milk','1 tbsp ground flaxseeds','Fresh berries','1 tsp honey'], ARRAY['Cook oats in milk 5 min.','Stir in flaxseeds.','Top with berries and honey.'], 3, 5, '{"omega3":"high","calcium":"high","fiber":"high","calories":280}'),
('Spinach & Paneer Paratha','Iron-rich spinach and protein-packed paneer stuffed flatbread.', 'mum', 'breakfast', 0, 36, 'meal', ARRAY['2 whole wheat parathas','½ cup spinach (blanched, chopped)','50g paneer (grated)','Pinch cumin','Ghee'], ARRAY['Mix spinach and paneer with cumin.','Stuff into paratha dough and roll.','Cook on tawa with ghee until golden.','Serve with yogurt.'], 10, 10, '{"iron":"high","protein":"high","calcium":"high","calories":320}'),
('Avocado Toast with Egg', 'Smashed avocado on multigrain toast topped with poached egg.', 'mum', 'breakfast', 0, 36, 'meal', ARRAY['2 slices multigrain bread','½ avocado','1 egg','Cherry tomatoes','Pinch chilli flakes'], ARRAY['Toast bread.','Smash avocado with chilli flakes.','Poach egg 3 min.','Assemble and top with tomatoes.'], 8, 5, '{"healthy_fats":"high","protein":"high","folate":"high","calories":340}'),
('Ragi Porridge',          'Finger millet porridge — exceptional calcium source for new mums.', 'mum', 'breakfast', 0, 36, 'meal', ARRAY['3 tbsp ragi flour','1½ cups milk','1 tbsp jaggery','Pinch cardamom','Chopped dates'], ARRAY['Mix ragi in small amount of cold milk.','Heat remaining milk; add ragi paste stirring constantly.','Cook 8 min until thick.','Add jaggery and cardamom.','Top with dates.'], 5, 8, '{"calcium":"very_high","iron":"high","calories":260}'),
('Moong Dal Cheela',       'Protein-packed green moong pancakes — light and easy to digest.', 'mum', 'breakfast', 0, 36, 'meal', ARRAY['½ cup moong dal (soaked 4h)','1 tbsp grated ginger','Green chilli (optional)','Onion','Coriander','Oil'], ARRAY['Blend soaked dal to smooth batter.','Add ginger, onion, coriander.','Pour onto hot oiled pan; spread thin.','Cook 3 min per side.'], 10, 10, '{"protein":"very_high","iron":"high","folate":"high","calories":240}');
INSERT INTO recipes (title, description, target, meal_slot, age_range_min_months, age_range_max_months, recipe_type, ingredients, instructions, prep_time_minutes, nutrition_info) VALUES
('Fruit & Nut Bowl',       'Seasonal fruits with a handful of mixed nuts for sustained energy.', 'mum', 'mid_morning', 0, 36, 'snack', ARRAY['1 banana','½ cup papaya (diced)','1 tbsp mixed nuts (almonds, walnuts)','1 tbsp pumpkin seeds'], ARRAY['Dice fruit into bowl.','Top with nuts and seeds.','Enjoy fresh.'], 5, '{"healthy_fats":"high","potassium":"high","omega3":"medium","calories":195}'),
('Yogurt & Granola Cup',   'Probiotic-rich yogurt with wholesome granola and kiwi.', 'mum', 'mid_morning', 0, 36, 'snack', ARRAY['1 cup full-fat yogurt','3 tbsp low-sugar granola','1 kiwi (sliced)'], ARRAY['Layer yogurt in cup.','Add granola.','Top with kiwi slices.'], 3, '{"calcium":"high","probiotics":"yes","vitamin_c":"high","calories":220}'),
('Peanut Butter Banana Toast','Wholegrain toast with peanut butter and banana slices.', 'mum', 'mid_morning', 0, 36, 'snack', ARRAY['1 slice wholegrain toast','1 tbsp peanut butter','½ banana (sliced)','1 tsp chia seeds'], ARRAY['Toast bread.','Spread peanut butter.','Top with banana and chia seeds.'], 3, '{"protein":"medium","healthy_fats":"high","omega3":"medium","calories":240}'),
('Dry Fruits Ladoo',       'Energy-dense sweet balls made from dates, nuts and seeds — traditional postpartum food.', 'mum', 'mid_morning', 0, 36, 'snack', ARRAY['5 dates (pitted)','2 tbsp mixed nuts','1 tbsp sesame seeds','1 tbsp desiccated coconut','Pinch cardamom'], ARRAY['Process dates in blender.','Mix in crushed nuts, seeds and coconut.','Roll into small balls.','Refrigerate 30 min.'], 10, '{"iron":"high","calcium":"high","healthy_fats":"high","calories":175}');
INSERT INTO recipes (title, description, target, meal_slot, age_range_min_months, age_range_max_months, recipe_type, ingredients, instructions, prep_time_minutes, cooking_time_minutes, nutrition_info) VALUES
('Dal Rice with Ghee',     'Classic comforting dal and rice — iron, protein and warming for postpartum recovery.', 'mum', 'lunch', 0, 36, 'meal', ARRAY['½ cup toor dal','1 cup basmati rice','1 tsp ghee','Turmeric','Cumin','Tomato','Onion'], ARRAY['Cook rice separately.','Pressure cook dal.','Temper with ghee, cumin, onion and tomato.','Serve dal over rice with a drizzle of ghee.'], 5, 25, '{"protein":"high","iron":"high","carbs":"high","calories":380}'),
('Salmon & Quinoa Bowl',   'Omega-3 packed salmon over quinoa with steamed greens.', 'mum', 'lunch', 0, 36, 'meal', ARRAY['120g salmon fillet','½ cup quinoa','Handful spinach','Cherry tomatoes','Lemon dressing'], ARRAY['Cook quinoa 15 min.','Bake salmon 15 min at 190°C.','Wilt spinach.','Assemble bowl; drizzle with lemon dressing.'], 5, 20, '{"omega3":"very_high","protein":"very_high","iron":"high","calories":420}'),
('Chicken & Chickpea Salad','Protein-rich salad with grilled chicken, chickpeas and leafy greens.', 'mum', 'lunch', 0, 36, 'meal', ARRAY['100g grilled chicken','½ cup chickpeas','Mixed salad leaves','Cherry tomatoes','Cucumber','Tahini dressing'], ARRAY['Grill chicken and slice.','Toss chickpeas and salad.','Add chicken on top.','Drizzle tahini dressing.'], 10, 10, '{"protein":"very_high","iron":"high","fiber":"high","calories":390}'),
('Pumpkin & Lentil Soup',  'Silky pumpkin and lentil soup loaded with vitamins and iron.', 'mum', 'lunch', 0, 36, 'meal', ARRAY['200g pumpkin','¼ cup red lentils','1 onion','2 cloves garlic','Vegetable stock','Cream'], ARRAY['Roast pumpkin at 200°C 20 min.','Sauté onion and garlic.','Add lentils and stock; simmer 20 min.','Blend smooth; stir in cream.'], 10, 40, '{"vitamin_a":"very_high","iron":"high","protein":"medium","calories":290}'),
('Rajma Chawal',           'Kidney beans curry with rice — classic iron and protein powerhouse.', 'mum', 'lunch', 0, 36, 'meal', ARRAY['½ cup rajma (kidney beans, cooked)','1 cup rice','Onion','Tomato','Ginger garlic paste','Spices','Ghee'], ARRAY['Cook rajma in pressure cooker.','Prepare onion-tomato gravy.','Add rajma; simmer 15 min.','Serve over steamed rice with ghee.'], 10, 30, '{"iron":"very_high","protein":"high","fiber":"high","calories":410}');
INSERT INTO recipes (title, description, target, meal_slot, age_range_min_months, age_range_max_months, recipe_type, ingredients, instructions, prep_time_minutes, cooking_time_minutes, nutrition_info) VALUES
('Masala Chai with Milk',  'Warm spiced tea with full-fat milk — comforting afternoon pick-me-up.', 'mum', 'evening', 0, 36, 'meal', ARRAY['1 cup whole milk','1 tea bag or 1 tsp loose tea','½ tsp ginger','Pinch cinnamon','1 tsp jaggery'], ARRAY['Boil milk with ginger and cinnamon.','Add tea; steep 3 min.','Strain; sweeten with jaggery.'], 2, 5, '{"calcium":"high","anti_inflammatory":"yes","calories":110}'),
('Roasted Makhana',        'Ghee-roasted fox nuts — crunchy calcium-rich snack.', 'mum', 'evening', 0, 36, 'snack', ARRAY['1 cup makhana (fox nuts)','1 tsp ghee','Pinch rock salt','Pinch pepper'], ARRAY['Heat ghee in pan.','Add makhana; roast stirring 5 min until crisp.','Sprinkle salt and pepper.','Cool and serve.'], 2, 5, '{"calcium":"high","protein":"medium","calories":160}'),
('Vegetable Soup',         'Light broth-based vegetable soup to bridge between lunch and dinner.', 'mum', 'evening', 0, 36, 'meal', ARRAY['Mixed veg (carrot, pea, corn, beans)','2 cups vegetable stock','1 tsp olive oil','Herbs'], ARRAY['Sauté veg in oil 3 min.','Add stock; simmer 15 min.','Season with herbs.'], 5, 15, '{"fiber":"high","vitamins":"high","calories":120}'),
('Hummus & Veggie Plate',  'Store-bought or homemade hummus with raw and lightly cooked vegetables.', 'mum', 'evening', 0, 36, 'snack', ARRAY['4 tbsp hummus','Carrot sticks','Cucumber sticks','Bell pepper strips','Multigrain crackers'], ARRAY['Arrange vegetables and crackers.','Serve with hummus for dipping.'], 5, 0, '{"protein":"medium","fiber":"high","iron":"medium","calories":175}');
INSERT INTO recipes (title, description, target, meal_slot, age_range_min_months, age_range_max_months, recipe_type, ingredients, instructions, prep_time_minutes, cooking_time_minutes, nutrition_info) VALUES
('Palak Paneer with Roti', 'Iron-loaded spinach curry with protein-rich paneer and whole wheat roti.', 'mum', 'dinner', 0, 36, 'meal', ARRAY['100g paneer','2 cups spinach','Onion','Tomato','Cream','Spices','Whole wheat roti'], ARRAY['Blanch and blend spinach.','Sauté onion, tomato and spices.','Add spinach puree; simmer 10 min.','Add paneer and cream.','Serve with roti.'], 10, 20, '{"iron":"very_high","protein":"high","calcium":"high","calories":380}'),
('Baked Herb Chicken',     'Oven-baked chicken breast with herbs and roasted vegetables.', 'mum', 'dinner', 0, 36, 'meal', ARRAY['150g chicken breast','Mixed herbs','Olive oil','Lemon','Broccoli','Sweet potato','Bell pepper'], ARRAY['Marinate chicken in herbs, oil and lemon 20 min.','Bake at 190°C 25 min.','Roast veg alongside last 20 min.','Serve together.'], 25, 25, '{"protein":"very_high","vitamin_a":"high","iron":"medium","calories":350}'),
('Fish Curry & Brown Rice','DHA-rich fish curry with fibre-packed brown rice.', 'mum', 'dinner', 0, 36, 'meal', ARRAY['150g fish (salmon or mackerel)','Coconut milk','Tomato','Onion','Curry leaves','Mustard seeds','Brown rice'], ARRAY['Cook brown rice 35 min.','Sauté onion with mustard seeds and curry leaves.','Add tomato; cook 5 min.','Add fish and coconut milk; simmer 12 min.','Serve over rice.'], 10, 35, '{"omega3":"very_high","protein":"high","fiber":"high","calories":420}'),
('Methi & Tofu Sabzi',     'Fenugreek leaves with tofu — iron-rich, calcium-packed and traditionally good for lactation.', 'mum', 'dinner', 0, 36, 'meal', ARRAY['1 bunch methi leaves','100g firm tofu','Onion','Tomato','Spices','Oil'], ARRAY['Press and cube tofu; pan-fry until golden.','Sauté onion and tomato with spices.','Add methi leaves; wilt 5 min.','Add tofu; mix gently.','Serve with roti or rice.'], 10, 15, '{"iron":"very_high","calcium":"high","galactagogue":"yes","calories":280}'),
('Pasta Primavera',        'Whole grain pasta with spring vegetables in olive oil and garlic.', 'mum', 'dinner', 0, 36, 'meal', ARRAY['100g whole grain pasta','Mixed veg (zucchini, cherry tomato, asparagus)','3 cloves garlic','Olive oil','Parmesan','Basil'], ARRAY['Cook pasta al dente.','Sauté garlic in oil 1 min.','Add veg; cook 5 min.','Toss pasta with veg.','Top with parmesan and basil.'], 5, 15, '{"fiber":"high","vitamin_c":"high","carbs":"high","calories":360}');
INSERT INTO recipes (title, description, target, meal_slot, age_range_min_months, age_range_max_months, recipe_type, ingredients, instructions, prep_time_minutes, cooking_time_minutes, nutrition_info) VALUES
('Golden Milk',            'Turmeric milk — anti-inflammatory, promotes sleep and supports recovery.', 'mum', 'bedtime', 0, 36, 'meal', ARRAY['1 cup warm whole milk','½ tsp turmeric','Pinch black pepper','Pinch cinnamon','½ tsp honey'], ARRAY['Warm milk gently.','Whisk in turmeric, pepper and cinnamon.','Sweeten with honey.','Drink warm.'], 3, 3, '{"calcium":"high","anti_inflammatory":"yes","tryptophan":"yes","calories":120}'),
('Warm Milk & Dates',      'Warm milk with soft dates — traditional sleep-promoting bedtime ritual.', 'mum', 'bedtime', 0, 36, 'meal', ARRAY['1 cup warm whole milk','2–3 Medjool dates (pitted)'], ARRAY['Warm milk.','Eat dates alongside warm milk.'], 2, 2, '{"calcium":"high","iron":"medium","magnesium":"high","calories":175}'),
('Chamomile & Honey Tea',  'Calming chamomile tea with honey to wind down before sleep.', 'mum', 'bedtime', 0, 36, 'meal', ARRAY['1 chamomile tea bag','1 cup hot water','1 tsp honey'], ARRAY['Steep chamomile in hot water 5 min.','Remove bag; stir in honey.','Drink while warm.'], 2, 5, '{"calming":"yes","anti_anxiety":"yes","calories":25}'),
('Banana & Almond Snack',  'Half banana with a few almonds — magnesium and tryptophan for better sleep.', 'mum', 'bedtime', 0, 36, 'snack', ARRAY['½ banana','5 almonds'], ARRAY['Slice banana.','Eat with almonds.'], 1, 0, '{"magnesium":"high","tryptophan":"yes","healthy_fats":"medium","calories":95}'),
('Ashwagandha Milk',       'Warm milk with ashwagandha — supports stress reduction and hormonal balance.', 'mum', 'bedtime', 0, 36, 'meal', ARRAY['1 cup warm whole milk','¼ tsp ashwagandha powder','1 tsp honey','Pinch cardamom'], ARRAY['Warm milk.','Whisk in ashwagandha and cardamom.','Sweeten with honey.'], 3, 3, '{"adaptogen":"yes","calcium":"high","stress_relief":"yes","calories":130}');
